from bisect import bisect_right
from itertools import combinations
from random import Random

SIZE_LIMIT = 200_000
VALUE_LIMIT = 1_000_000_000


def _integer(token: str) -> int | None:
    negative = token.startswith("-")
    digits = token[1:] if token.startswith(("+", "-")) else token
    if not digits.isascii() or not digits.isdecimal():
        return None
    significant = digits.lstrip("0")
    if len(significant) > 10:
        magnitude = VALUE_LIMIT + 1
    else:
        magnitude = int(significant or "0")
    return -magnitude if negative else magnitude


def _parse(inp: str) -> tuple[
    list[int], list[tuple[int, int]], list[int]
] | None:
    rows = inp.splitlines()
    if len(rows) < 3:
        return None

    header = rows[0].split()
    if len(header) != 2:
        return None
    size, query_count = map(_integer, header)
    if size is None or query_count is None:
        return None
    if not (1 <= size <= SIZE_LIMIT and 1 <= query_count <= SIZE_LIMIT):
        return None
    if len(rows) != query_count + 2:
        return None

    tokens = rows[1].split()
    if len(tokens) != size:
        return None
    values = []
    prefix_minimum = [VALUE_LIMIT]
    for token in tokens:
        value = _integer(token)
        if value is None or not 1 <= value <= VALUE_LIMIT:
            return None
        values.append(value)
        prefix_minimum.append(min(prefix_minimum[-1], value))

    queries = []
    for row in rows[2:]:
        fields = row.split()
        if len(fields) != 2:
            return None
        right, threshold = map(_integer, fields)
        if right is None or threshold is None or not 1 <= right <= size:
            return None
        if not prefix_minimum[right] <= threshold <= VALUE_LIMIT:
            return None
        queries.append((right, threshold))
    return values, queries, prefix_minimum


def _encode(values: list[int], queries: list[tuple[int, int]]) -> str:
    rows = [f"{len(values)} {len(queries)}", " ".join(map(str, values))]
    rows.extend(f"{right} {threshold}" for right, threshold in queries)
    return "\n".join(rows) + "\n"


def validate_input(inp: str) -> bool:
    return _parse(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = Random(seed)
    cases = [
        ([1], [(1, 1)]),
        ([VALUE_LIMIT], [(1, VALUE_LIMIT)]),
        ([4, 4, 4, 4], [(4, 4), (1, 4), (4, VALUE_LIMIT), (4, 4)]),
        ([6, 5, 4, 3, 2, 1], [(6, 1), (3, 5), (6, 6), (1, 6)]),
        ([1, 2, 3, 4, 5, 6], [(6, 6), (6, 3), (2, 3), (6, 1)]),
        ([2, 4, 1, 3, 3], [(2, 5), (5, 2), (5, 3), (3, 1)]),
        (
            [1, VALUE_LIMIT, VALUE_LIMIT - 1, VALUE_LIMIT, 1],
            [(5, VALUE_LIMIT - 1), (2, VALUE_LIMIT), (5, VALUE_LIMIT)],
        ),
    ]
    result = [_encode(values, queries) for values, queries in cases[:max(0, n)]]
    while len(result) < n:
        size = rng.randint(1, 8)
        pool = rng.choice(((1, 2, 3), tuple(range(1, 17)),
                           (1, 2, VALUE_LIMIT - 1, VALUE_LIMIT)))
        values = [rng.choice(pool) for _ in range(size)]
        queries = []
        for _ in range(rng.randint(1, 8)):
            right = rng.randint(1, size)
            minimum = min(values[:right])
            threshold = rng.choice((
                minimum, VALUE_LIMIT, values[rng.randrange(right)],
                rng.randint(minimum, VALUE_LIMIT),
            ))
            queries.append((right, threshold))
        result.append(_encode(values, queries))
    return result


def gen_stress(seed: int) -> list[str]:
    rng = Random(seed)
    size = SIZE_LIMIT

    rising = list(range(1, size + 1))
    rising_queries = [
        (size, size), (1, 1), (size, 1), (size, VALUE_LIMIT),
    ]
    while len(rising_queries) < SIZE_LIMIT:
        right = rng.randint(size // 2, size)
        threshold = rng.randint(size // 3, size + size // 3)
        rising_queries.append((right, threshold))

    mixed = [1]
    for index in range(size - 1):
        block, offset = divmod(index, 64)
        if offset % 2 == 0:
            mixed.append(2 + block * 32 + (63 - offset) // 4)
        else:
            mixed.append(VALUE_LIMIT - index // 4)

    mixed_queries = [(size, VALUE_LIMIT), (size, 1), (1, VALUE_LIMIT)]
    while len(mixed_queries) < SIZE_LIMIT:
        right = rng.randint(size // 2, size)
        threshold = rng.choice((
            mixed[rng.randrange(right)],
            rng.randint(1, size),
            VALUE_LIMIT,
        ))
        mixed_queries.append((right, threshold))

    return [_encode(rising, rising_queries), _encode(mixed, mixed_queries)]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    parsed = _parse(inp)
    if parsed is None:
        return [("POST-1", "Input does not satisfy the input format or bounds.")]
    values, queries, prefix_minimum = parsed

    rows = out.splitlines()
    if len(rows) != len(queries):
        return [("POST-2", f"Expected {len(queries)} output lines, got {len(rows)}.")]

    answers = []
    for number, row in enumerate(rows, 1):
        fields = row.split()
        answer = _integer(fields[0]) if len(fields) == 1 else None
        if answer is None:
            return [("POST-2", f"Line {number} must contain one decimal integer.")]
        answers.append(answer)

    seen = set()
    prefix_distinct = [0]
    first_rise = len(values) + 1
    for index, value in enumerate(values, 1):
        seen.add(value)
        prefix_distinct.append(len(seen))
        if index > 1 and first_rise > len(values) and values[index - 2] < value:
            first_rise = index
    distinct_values = sorted(seen)

    violations = []
    by_query = {}
    for number, ((right, threshold), answer) in enumerate(zip(queries, answers), 1):
        upper = min(
            prefix_distinct[right],
            bisect_right(distinct_values, threshold),
            threshold - prefix_minimum[right] + 1,
        )
        if right < first_rise:
            upper = 1
        if not 1 <= answer <= upper and not violations:
            violations.append((
                "POST-4", f"Answer {number} must be between 1 and {upper}.",
            ))

        previous = by_query.setdefault((right, threshold), answer)
        if previous != answer:
            violations.append((
                "POST-5", f"Query {number} repeats an earlier query with a different answer.",
            ))
            return violations

    for varying in (0, 1):
        fixed = 1 - varying
        ordered = sorted(by_query, key=lambda query: (query[fixed], query[varying]))
        for first, second in zip(ordered, ordered[1:]):
            if first[fixed] != second[fixed]:
                continue
            change = by_query[second] - by_query[first]
            available = second[varying] - first[varying]
            if not 0 <= change <= available:
                violations.append((
                    "POST-5",
                    f"Answers for {first} and {second} violate monotonicity "
                    "or the bound on their difference.",
                ))
                return violations
    return violations


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = Random(seed)
    result = []
    for index in range(n):
        size = rng.randint(2, 8)
        values = [rng.randint(1, 16) for _ in range(size)]
        variant = index % 4

        if variant == 0:
            queries = [
                (right, rng.randint(min(values[:right]), 16))
                for right in range(size, 0, -1)
            ]
            shift = rng.randint(1, VALUE_LIMIT - 16)
            shifted_values = [value + shift for value in values]
            shifted_queries = [(right, threshold + shift) for right, threshold in queries]
            result.append((
                "POST-5", "equal", _encode(values, queries),
                _encode(shifted_values, shifted_queries),
            ))
        elif variant == 1:
            queries = [
                (right, rng.randint(min(values[:right]), 16))
                for right in range(size, 0, -1)
            ]
            position = rng.randrange(size + 1)
            extended = values[:position] + [VALUE_LIMIT] + values[position:]
            adjusted = [
                (right + int(position < right), threshold)
                for right, threshold in queries
            ]
            result.append((
                "POST-5", "equal", _encode(values, queries), _encode(extended, adjusted),
            ))
        elif variant == 2:
            left_right = rng.randint(1, size - 1)
            right_right = rng.randint(left_right + 1, size)
            threshold = rng.randint(min(values[:left_right]), 16)
            result.append((
                "POST-5", "le", _encode(values, [(left_right, threshold)]),
                _encode(values, [(right_right, threshold)]),
            ))
        else:
            right = rng.randint(1, size)
            lower = rng.randint(min(values[:right]), 16)
            upper = rng.randint(lower + 1, 17)
            result.append((
                "POST-5", "le", _encode(values, [(right, lower)]),
                _encode(values, [(right, upper)]),
            ))
    return result


def reference_small(inp: str) -> str | None:
    parsed = _parse(inp)
    if parsed is None:
        return None
    values, queries, _ = parsed
    if len(values) > 12 or len(queries) > 64:
        return None

    answers = []
    for right, threshold in queries:
        best = 0
        prefix = values[:right]
        for length in range(1, right + 1):
            for subsequence in combinations(prefix, length):
                if all(value <= threshold for value in subsequence) and all(
                    left < right_value
                    for left, right_value in zip(subsequence, subsequence[1:])
                ):
                    best = length
        answers.append(str(best))
    return "\n".join(answers) + "\n"
